/* Archivo (OFL-1.1, Google Fonts) — embedded so the serverless PDF route needs no font files on disk. */
export const ARCHIVO_REGULAR_B64 = "";
export const ARCHIVO_BOLD_B64 = "";
export const ARCHIVO_BLACK_B64 = "";
export const bytes = (b64: string): Uint8Array => Uint8Array.from(Buffer.from(b64, "base64"));
